#!/usr/bin/env python3
"""Gera guia-atb.html a partir de tools/guia-antibioticos.md.
Uso (na raiz do repositório):  python3 tools/build_guia_atb.py
Requer: pandoc. Depois: subir a versão em sw.js (constante C) para os aparelhos atualizarem.
"""
import re, subprocess, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
md = root / "tools" / "guia-antibioticos.md"
full = subprocess.run(["pandoc", str(md), "-f", "gfm", "-t", "html5", "--toc", "--toc-depth=2", "-s",
                       "--metadata", "title=Guia ATB"], capture_output=True, text=True, check=True).stdout
toc = re.search(r'<nav id="TOC"[^>]*>(.*?)</nav>', full, re.S).group(1)
body = re.search(r"<body>(.*)</body>", full, re.S).group(1)
body = re.sub(r"<header.*?</header>", "", body, flags=re.S)
body = re.sub(r'<nav id="TOC".*?</nav>', "", body, flags=re.S)
body = body.replace("<table>", '<div class="tw"><table>').replace("</table>", "</table></div>")
body = body.replace("🏥", '<span class="b h" title="hospitalar">🏥</span>')
HEAD = '<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Guia ATB — Fichas de Plantão</title>\n<meta name="description" content="Guia de antibióticos: quando escalonar, descalonar, características de cada antibiótico e escolha por infecção. Uso profissional.">\n<link rel="manifest" href="manifest.webmanifest">\n<link rel="icon" href="icons/icon-192.png">\n<meta name="theme-color" content="#1f7a80">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=Literata:opsz,wght@7..72,600&display=swap" rel="stylesheet">\n<style>\n:root{--bg:#f3f6f7;--panel:#fff;--ink:#16262c;--muted:#5b6d73;--line:#d6e0e3;--accent:#0b6e75;--accent-soft:#e1f0f1;--warn:#b4471b;--warn-soft:#fbeae2;--code:#eef3f4;--f-display:"Literata",Georgia,serif;--f-body:"IBM Plex Sans",system-ui,sans-serif;color-scheme:light}\n@media (prefers-color-scheme:dark){:root{--bg:#0f181b;--panel:#152226;--ink:#e3eced;--muted:#93a7ac;--line:#26383d;--accent:#4fb8bf;--accent-soft:#173539;--warn:#f08a5d;--warn-soft:#3a2219;--code:#1b2b30;color-scheme:dark}}\n*{box-sizing:border-box}\nhtml{scroll-padding-top:70px}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 var(--f-body)}\na{color:var(--accent)}\nheader.bar{position:sticky;top:0;z-index:5;background:var(--panel);border-bottom:1px solid var(--line);padding:10px 16px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}\n.brand{font-family:var(--f-display);font-size:19px;margin-right:auto}\n.brand small{display:block;font:12px var(--f-body);color:var(--muted)}\n.back{border:1px solid var(--line);border-radius:99px;padding:6px 14px;text-decoration:none;font-size:14px;background:var(--panel)}\n#q{padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);min-width:200px;font:inherit;color:inherit}\n.wrap{display:grid;grid-template-columns:270px minmax(0,1fr);max-width:1400px;margin:0 auto}\nnav.toc{position:sticky;top:58px;align-self:start;max-height:calc(100vh - 58px);overflow:auto;padding:16px 12px 40px 16px;border-right:1px solid var(--line);font-size:13.5px}\nnav.toc ul{list-style:none;margin:0;padding-left:10px}\nnav.toc>ul{padding-left:0}\nnav.toc li{margin:3px 0}\nnav.toc a{text-decoration:none;color:var(--ink)}\nnav.toc a:hover{color:var(--accent)}\nnav.toc>ul>li>a{font-weight:600}\nmain{padding:8px 28px 60px;min-width:0}\nh1{font-family:var(--f-display);font-size:28px;margin:18px 0 6px}\nh2{font-family:var(--f-display);font-size:22px;margin:34px 0 8px;padding-top:12px;border-top:2px solid var(--accent-soft)}\nh3{font-size:17px;margin:24px 0 6px;color:var(--accent)}\n.tw{overflow-x:auto;margin:10px 0 16px;border:1px solid var(--line);border-radius:10px;background:var(--panel)}\ntable{border-collapse:collapse;width:100%;font-size:14px}\nth,td{padding:7px 10px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\nth{background:var(--accent-soft);font-weight:600;position:sticky;top:0}\ntr:last-child td{border-bottom:0}\nblockquote,.aviso{margin:12px 0;padding:10px 14px;border-left:4px solid var(--warn);background:var(--warn-soft);border-radius:6px}\nhr{border:0;border-top:1px solid var(--line);margin:24px 0}\ncode{background:var(--code);padding:1px 4px;border-radius:4px}\nmark{background:#ffe58a;color:#16262c}\n.hide{display:none}\nfooter{font-size:12.5px;color:var(--muted);padding:20px 28px;border-top:1px solid var(--line)}\n#totop{position:fixed;right:14px;bottom:14px;border:0;border-radius:99px;padding:10px 14px;background:var(--accent);color:#fff;cursor:pointer;box-shadow:0 2px 8px #0003}\n@media (max-width:860px){.wrap{grid-template-columns:1fr}nav.toc{position:static;max-height:none;border-right:0;border-bottom:1px solid var(--line)}nav.toc details:not([open]) ul{display:none}main{padding:4px 14px 60px}#q{min-width:0;flex:1}}\n@media print{header.bar,nav.toc,#totop{display:none}.wrap{display:block}th{position:static}}\n</style>\n</head>\n<body>\n<header class="bar">\n  <div class="brand">Guia ATB<small>Escalonar, descalonar, características e escolha por infecção · REMUME Goioerê</small></div>\n  <input id="q" type="search" placeholder="Filtrar (ex.: ESBL, celulite, gestante)" aria-label="Filtrar o guia">\n  <a class="back" href="./">← Fichas de Plantão</a>\n</header>\n<div class="wrap">\n'
TAIL = '</main>\n</div>\n<footer>Guia ATB · versão 22/11/2026 · Fichas de Plantão. Apoio à decisão para uso profissional; não substitui julgamento clínico, bula ou protocolo da CCIH. Doses de adulto com função renal normal salvo indicação; pediatria sempre por peso com dupla checagem. Disponibilidade: REMUME Goioerê 2022 (confirmar na farmácia).</footer>\n<button id="totop" title="Voltar ao topo" aria-label="Voltar ao topo">↑</button>\n<script>\ndocument.getElementById(\'totop\').onclick=()=>scrollTo({top:0,behavior:\'smooth\'});\nif(matchMedia(\'(max-width:860px)\').matches) document.querySelector(\'nav.toc details\').removeAttribute(\'open\');\nconst q=document.getElementById(\'q\'), main=document.getElementById(\'main\');\nconst blocks=[...main.querySelectorAll(\'tr, li, p\')];\nq.addEventListener(\'input\',()=>{\n  const t=q.value.trim().toLowerCase().normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g,\'\');\n  blocks.forEach(b=>{ if(b.closest(\'thead\')) return;\n    const s=b.textContent.toLowerCase().normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g,\'\');\n    b.classList.toggle(\'hide\', !!t && !s.includes(t)); });\n  main.querySelectorAll(\'h2,h3\').forEach(h=>h.classList.toggle(\'hide\',!!t));\n  main.querySelectorAll(\'.tw\').forEach(w=>{const rows=w.querySelectorAll(\'tbody tr\'); w.classList.toggle(\'hide\', !!t && rows.length && [...rows].every(r=>r.classList.contains(\'hide\')));});\n  main.querySelectorAll(\'hr,h1,ul,ol\').forEach(x=>{ if(x.tagName===\'UL\'||x.tagName===\'OL\'){ x.classList.toggle(\'hide\', !!t && [...x.children].every(li=>li.classList.contains(\'hide\'))); } else x.classList.toggle(\'hide\',!!t); });\n});\nif(\'serviceWorker\' in navigator) navigator.serviceWorker.register(\'sw.js\').catch(()=>{});\n</script>\n</body>\n</html>'
html = HEAD + '<nav class="toc" aria-label="Sumário"><details open><summary><b>Sumário</b></summary>' + toc + '</details></nav>\n<main id="main">\n' + body + "\n" + TAIL
(root / "guia-atb.html").write_text(html, encoding="utf-8")
print("guia-atb.html gerado:", len(html), "bytes")
